import overload from "@jyostudio/overload";
import message from "../messages/message.js";

const CONSTURCTOR_SYMBOL = Symbol("constructor");

export default class Exception extends Error {
    static [CONSTURCTOR_SYMBOL] = function (...params) {
        Exception[CONSTURCTOR_SYMBOL] = overload()
            .add([String], function (msg) {
                this.message = message[msg] ?? msg;
            })
            .any(function (msg, ...params) {
                const _msg = message[msg] ?? msg;
                this.message = _msg.replace(/\{(\d+)\}/g,
                    function (m, i) {
                        return params[i];
                    });
            });

        return Exception[CONSTURCTOR_SYMBOL].apply(this, params);
    }

    constructor(...params) {
        super(...params);

        this.name = this.constructor.name;

        Exception[CONSTURCTOR_SYMBOL].apply(this, params);

        let newStack = "";
        this.stack.split('\n').forEach((s, i) => {
            newStack += `${i ? '\n' : ''}${s}`;
        });
        this.stack = newStack;
    }
}
