import zhCN from "./zh-CN.json" with { type: "json" };
import enUS from "./en-US.json" with { type: "json" };

let lang = null;
switch (process.env.lang) {
    case "zh-CN":
        lang = zhCN;
        break;
    case "en-US":
        lang = enUS;
        break;
    default:
        lang = zhCN;
        break;
}

export default lang;